mapper.select:
SELECT DISTINCT LINING_CODE FROM T_NC_SCHEDULE_RESULT WHERE FACTORY_CODE = #{factoryCode} AND SCHEDULE_DATE BETWEEN #{thresholdDate} AND #{scheduleDate} AND LINING_CODE IN
#{code}
AND (CLASS1_PLAN_QTY IS NOT NULL AND CLASS1_PLAN_QTY > 0 OR CLASS2_PLAN_QTY IS NOT NULL AND CLASS2_PLAN_QTY > 0 OR CLASS3_PLAN_QTY IS NOT NULL AND CLASS3_PLAN_QTY > 0 OR CLASS4_PLAN_QTY IS NOT NULL AND CLASS4_PLAN_QTY > 0 OR CLASS5_PLAN_QTY IS NOT NULL AND CLASS5_PLAN_QTY > 0 OR CLASS6_PLAN_QTY IS NOT NULL AND CLASS6_PLAN_QTY > 0)
